const body = $input.first().json.body ?? $input.first().json;
const message = body.message ?? body.edited_message ?? body.channel_post ?? {};
const chatId = message.chat?.id;
const rawText = String(message.text ?? message.caption ?? '').trim();
const hasAudio = Boolean(message.voice || message.audio || (message.document?.mime_type || '').startsWith('audio/'));
const lower = rawText.toLowerCase();
const isCommand = /^\/(music|song|loop|beat)(@\w+)?(\s|$)/i.test(rawText);
const hasMusicWords = ['song','track','beat','loop','music','synthwave','lofi','techno','house','ambient','piano'].some(w => lower.includes(w));
const hasActionWords = ['make','create','generate','compose','turn','remix'].some(w => lower.includes(w));
const isMusic = hasAudio || isCommand || lower.startsWith('music:') || lower.startsWith('song:') || lower.startsWith('loop:') || lower.startsWith('beat:') || (hasMusicWords && hasActionWords);

if (!chatId || !isMusic) {
  return [];
}

let prompt = rawText
  .replace(/^\/(music|song|loop|beat)(@\w+)?\s*/i, '')
  .replace(/^(music|song|loop|beat):\s*/i, '')
  .trim();
if (!prompt && hasAudio) {
  prompt = 'Create an original loop from this uploaded audio clip. Preserve its rhythmic or melodic idea and build a fuller musical sketch around it.';
}
if (!prompt) {
  prompt = 'Create an original instrumental music cue.';
}

return [{ json: {
  prompt,
  chat_id: chatId,
  message_id: message.message_id ?? null,
  username: message.from?.username ?? '',
  first_name: message.from?.first_name ?? '',
  duration_seconds: 90
} }];

const token = process.env.TELEGRAM_BOT_TOKEN;
if (!token) {
  throw new Error('TELEGRAM_BOT_TOKEN is not set in the n8n service environment.');
}

const result = $input.first().json;
const source = $('Extract Telegram Message').item.json;
const text = result.status === 'completed'
  ? `Done: ${result.output_path}`
  : `Music job failed: ${result.error || result.status || 'unknown error'}`;

const response = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    chat_id: source.chat_id,
    reply_to_message_id: source.message_id || undefined,
    text
  })
});

if (!response.ok) {
  throw new Error(`Telegram sendMessage failed: ${response.status} ${await response.text()}`);
}

return [{ json: { sent: true, chat_id: source.chat_id, output_path: result.output_path ?? null, status: result.status } }];
